import { detectChange, deadlineCalc, form410s1, form410s2Lines, feeBatchSchedule, precludeAndWriteOff, resolveFeeItems, collectibleFees, noticeDeadline180, responseDueCourt, challengeDeadlineCourt, rollForward9006Court, statusResponse, g4MotionWindow, timeliness9006, renderCourtForm, computationHash, ingestFeeItem, planCompletionFreeze, responseTrigger, effectiveOnDueDate, figuresRequest, b4MotionHold, applyCourtOrder, reliefOrderDecision, supersedingNotice, armChangeNotice, PART_FOR_SOURCE, OFFICER_WRITE_OFF_THRESHOLD_CENTS, RULE_SET_VERSION, type CaseFacts, type ChangeSource, type Form410c13nInput, type PostpetitionFeeItem, type ResponseKind, type StatedFacts, type FrozenLedgerViews, type NoticeStatus } from "../../domain/bankruptcy/ops-14-2.ts";

const need = (i: ToolInput, ...keys: string[]): void => { for (const k of keys) if (i[k] === undefined || i[k] === null || i[k] === "") throw new RangeError(`${k} is required`); };
const date = (i: ToolInput, k: string): PlainDate => { need(i, k); return D(str(i, k)); };
const optDate = (i: ToolInput, k: string): PlainDate | null => (i[k] === undefined || i[k] === null || i[k] === "" ? null : D(str(i, k)));
const optCents = (v: unknown): bigint | null => (v === undefined || v === null || v === "" ? null : cents(v));
const optStr = (i: ToolInput, k: string): string | null => (i[k] === undefined || i[k] === null || i[k] === "" ? null : String(i[k]));
const AGENT = "bankruptcy-ops";
const FILING_TYPE_RE = /^(s1_payment_change|s2_fee_notice|m1r_status_response|nr_final_cure_response|m2r_motion_response)$/;
const ESCALATION_KINDS = /^(signing_officer|attorney|officer|human_agent|sev[1-4])$/;
